//! `iglint generate-docs`: the rule reference in `docs/rules/`, generated
//! from the rule metadata. A test keeps the committed files up to date.

use std::path::{Path, PathBuf};

use iglint_linter::Registry;
use iglint_linter::registry::{Category, FixAvailability, RuleCode};

use crate::args::GenerateDocsArgs;
use crate::commands::{fix_text, option_type};
use crate::{Environment, ExitStatus, Io};

const HEADER: &str =
    "<!-- Generated by `iglint generate-docs` from the rule metadata. Do not edit. -->\n\n";

/// Escapes `|` so that the text stays inside one Markdown table cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

/// The anchor GitHub gives the category heading in the index.
fn category_anchor(category: Category) -> String {
    format!(
        "{}-{}",
        category.title().to_lowercase().replace(' ', "-"),
        category.prefix().to_lowercase()
    )
}

/// The Markdown page of one rule.
pub fn rule_page(rule: RuleCode) -> String {
    let meta = rule.meta();
    let mut out = String::from(HEADER);
    out.push_str(&format!("# {}: {}\n\n", meta.code, meta.name));
    if !meta.summary.is_empty() {
        out.push_str(&format!("{}\n\n", meta.summary));
    }
    let ign_lint = if meta.ign_lint_names.is_empty() {
        "none".to_owned()
    } else {
        meta.ign_lint_names
            .iter()
            .map(|n| format!("`{n}`"))
            .collect::<Vec<_>>()
            .join(", ")
    };
    out.push_str("| | |\n|---|---|\n");
    out.push_str(&format!("| Code | `{}` |\n", meta.code));
    out.push_str(&format!("| Name | `{}` |\n", meta.name));
    out.push_str(&format!(
        "| Category | [{}](README.md#{}) (`{}`) |\n",
        meta.category.title(),
        category_anchor(meta.category),
        meta.category.prefix()
    ));
    out.push_str(&format!(
        "| Default severity | {} |\n",
        meta.default_severity
    ));
    out.push_str(&format!(
        "| Enabled by default | {} |\n",
        if meta.default_enabled { "yes" } else { "no" }
    ));
    out.push_str(&format!("| Fix available | {} |\n", fix_text(meta.fix)));
    out.push_str(&format!("| ign-lint equivalent | {ign_lint} |\n"));
    if !meta.explanation.is_empty() {
        out.push('\n');
        out.push_str(meta.explanation.trim_end());
        out.push('\n');
    }
    if !meta.options.is_empty() {
        out.push_str(&format!(
            "\n## Option reference\n\nSet in `[rules.{}]` of `iglint.toml` (or `[tool.iglint.rules.{}]` in `pyproject.toml`).\n\n| Option | Type | Default | Description |\n|---|---|---|---|\n",
            meta.code, meta.code
        ));
        for option in meta.options {
            let default = option.default.trim();
            let default = if matches!(default, "" | "none") {
                "none".to_owned()
            } else {
                format!("`{}`", cell(default))
            };
            out.push_str(&format!(
                "| `{}` | {} | {} | {} |\n",
                option.name,
                option_type(option.ty),
                default,
                cell(option.description)
            ));
        }
        if !meta.ign_lint_option_map.is_empty() {
            let pairs: Vec<String> = meta
                .ign_lint_option_map
                .iter()
                .map(|(from, to)| format!("`{from}` -> `{to}`"))
                .collect();
            out.push_str(&format!(
                "\nign-lint `kwargs` in a `rule_config.json`: {}.\n",
                pairs.join(", ")
            ));
        }
    }
    out
}

/// The index page, one table per category.
pub fn index(registry: &Registry) -> String {
    let mut out = String::from(HEADER);
    out.push_str("# Rules\n\n");
    out.push_str(&format!(
        "iglint has {} rules. Rules with *yes* in the Default column run without configuration; \
         enable the others with `select` or `extend-select` (see the \
         [configuration](../../README.md#configuration)). Fix: *always* or \
         *sometimes* means `iglint check --fix` can repair findings of the rule \
         (unsafe fixes also need `--unsafe-fixes`).\n\n\
         `iglint rule <CODE>` prints the same documentation in the terminal.\n",
        registry.len()
    ));
    for category in Category::ALL {
        let rules: Vec<RuleCode> = registry
            .iter()
            .filter(|r| r.meta().category == category)
            .collect();
        if rules.is_empty() {
            continue;
        }
        out.push_str(&format!(
            "\n## {} (`{}`)\n\n| Code | Name | Summary | Severity | Default | Fix |\n|---|---|---|---|---|---|\n",
            category.title(),
            category.prefix()
        ));
        for rule in rules {
            let meta = rule.meta();
            out.push_str(&format!(
                "| [{code}]({code}.md) | `{name}` | {summary} | {severity} | {default} | {fix} |\n",
                code = meta.code,
                name = meta.name,
                summary = cell(meta.summary),
                severity = meta.default_severity,
                default = if meta.default_enabled { "yes" } else { "" },
                fix = if meta.fix == FixAvailability::None {
                    ""
                } else {
                    fix_text(meta.fix)
                },
            ));
        }
    }
    out
}

/// Every file of `docs/rules/`, as `(file name, contents)`, sorted by name.
pub fn generate(registry: &Registry) -> Vec<(String, String)> {
    let mut files: Vec<(String, String)> = registry
        .iter()
        .map(|rule| (format!("{}.md", rule.code()), rule_page(rule)))
        .collect();
    files.push(("README.md".to_owned(), index(registry)));
    files.sort();
    files
}

/// Differences between the generated docs and `dir`: files that are
/// missing, outdated, or no longer generated.
pub fn stale(registry: &Registry, dir: &Path) -> Vec<String> {
    let generated = generate(registry);
    let mut problems = Vec::new();
    for (name, contents) in &generated {
        match std::fs::read_to_string(dir.join(name)) {
            Ok(existing) if existing.replace("\r\n", "\n") == *contents => {}
            Ok(_) => problems.push(format!("{name} is outdated")),
            Err(_) => problems.push(format!("{name} is missing")),
        }
    }
    for name in extra_files(dir, &generated) {
        problems.push(format!("{name} is not generated by any rule"));
    }
    problems
}

/// `*.md` files in `dir` that are not generated.
fn extra_files(dir: &Path, generated: &[(String, String)]) -> Vec<String> {
    let mut extra: Vec<String> = std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .flatten()
        .filter_map(|entry| entry.file_name().into_string().ok())
        .filter(|name| name.ends_with(".md") && !generated.iter().any(|(n, _)| n == name))
        .collect();
    extra.sort();
    extra
}

pub fn run(args: &GenerateDocsArgs, environment: &Environment, io: &mut Io<'_>) -> ExitStatus {
    let registry = environment.registry;
    let dir: PathBuf = iglint_config::absolutize(&environment.cwd, &args.output_dir);
    if args.check {
        let problems = stale(registry, &dir);
        if problems.is_empty() {
            let _ = writeln!(io.stdout, "{} is up to date.", args.output_dir.display());
            return ExitStatus::Success;
        }
        for problem in problems {
            let _ = writeln!(io.stderr, "{problem}");
        }
        let _ = writeln!(
            io.stderr,
            "error: the rule docs are stale; run `cargo run -p iglint -- generate-docs`"
        );
        return ExitStatus::Failure;
    }
    if let Err(error) = std::fs::create_dir_all(&dir) {
        let _ = writeln!(io.stderr, "error: cannot create {}: {error}", dir.display());
        return ExitStatus::Error;
    }
    let generated = generate(registry);
    for name in extra_files(&dir, &generated) {
        if let Err(error) = std::fs::remove_file(dir.join(&name)) {
            let _ = writeln!(io.stderr, "error: cannot remove {name}: {error}");
            return ExitStatus::Error;
        }
    }
    for (name, contents) in &generated {
        if let Err(error) = std::fs::write(dir.join(name), contents) {
            let _ = writeln!(io.stderr, "error: cannot write {name}: {error}");
            return ExitStatus::Error;
        }
    }
    let _ = writeln!(
        io.stdout,
        "Wrote {} files to {}.",
        generated.len(),
        args.output_dir.display()
    );
    ExitStatus::Success
}
